var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var rig=root.GetComponent<Character.Control.PaddleCharacterVisual>();
 for(int i=0;i<12;i++){
  rig.Pose();
  var transient=root.GetComponentsInChildren<UnityEngine.SpriteRenderer>().Where(x=>x.name.StartsWith("Grip palm ")||x.name.StartsWith("Forearm segment ")).ToArray();
  if(transient.Length!=4)throw new System.Exception("Duplicate visual parts "+transient.Length);
  if(!rig.leftLower.sprite||!rig.rightLower.sprite||!UnityEditor.AssetDatabase.Contains(rig.leftLower.sprite)||!UnityEditor.AssetDatabase.Contains(rig.rightLower.sprite))throw new System.Exception("Original sprite reference lost");
  rig.enabled=false;
  if(root.GetComponentsInChildren<UnityEngine.SpriteRenderer>().Any(x=>x.name.StartsWith("Grip palm ")||x.name.StartsWith("Forearm segment ")))throw new System.Exception("Transient visual leak");
  rig.enabled=true;
 }
 UnityEngine.Debug.Log("PASS 12 rebuild/cleanup cycles, four transient parts, original asset references intact");
 System.IO.File.WriteAllText("scripts/player-natural-grip-20261111/lifecycle.txt","PASS 12 rebuild/cleanup cycles, four transient parts, original asset references intact");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
